srun --mpi=pmix --exact --kill-on-bad-exit=1 --nodes=1 --ntasks=2 --ntasks-per-node=2 --cpu-bind=none --gpus-per-node=h100:2 --gpu-bind=none --distribution=block:block julia --startup-file=no --threads=1 --project=/home/anditse/Breeze.jl/.runtime/studies/weak_scaling_mpi_2026-11-12_nx1/environment -e 'using MPI; MPI.Init(); using CUDA, Oceananigans, Breeze, Printf; using Oceananigans.DistributedComputations: Distributed, Partition; count = MPI.Comm_size(MPI.COMM_WORLD); rank = MPI.Comm_rank(MPI.COMM_WORLD); arch = count == 1 ? GPU() : Distributed(GPU(); partition=Partition(count, 1)); @printf("PREFLIGHT rank=%d host=%s gpu_uuid=%s devices=%d\n", rank, gethostname(), string(CUDA.uuid(CUDA.device())), length(CUDA.devices())); CUDA.functional() && MPI.has_cuda() || error("CUDA-aware MPI and a functional GPU are required"); if rank == 0; CUDA.versioninfo(); MPI.versioninfo(); println("Breeze path: ", pathof(Breeze)); end; MPI.Barrier(MPI.COMM_WORLD)'
